#!/usr/bin/env python3
"""
Ambient Context Retrieval Demo for Percept Dashboard
Offline and deterministic - processes conversations to extract entities and build relationships.
"""

import json
import csv
import re
from pathlib import Path
from datetime import datetime

# Entity extraction patterns
PEOPLE_PATTERNS = [
    r'\bAvery\b',
    r'\bJordan\b',
    r'\bMina\b',
]

PROJECT_PATTERNS = [
    r'\bProject Lumen\b',
    r'\bambient dashboard\b',
    r'\bsearch index\b',
]

ORGANIZATION_PATTERNS = [
    r'\bNorthstar Labs\b',
]

DATE_PATTERNS = [
    r'\bFriday\b',
    r'\d{4}-\d{2}-\d{2}',
]

def extract_entities(text):
    """Extract entities from text using regex patterns."""
    entities = []

    # Extract people
    for pattern in PEOPLE_PATTERNS:
        for match in re.finditer(pattern, text, re.IGNORECASE):
            entities.append({
                'text': match.group(),
                'type': 'person',
                'start': match.start(),
                'end': match.end()
            })

    # Extract projects
    for pattern in PROJECT_PATTERNS:
        for match in re.finditer(pattern, text, re.IGNORECASE):
            entities.append({
                'text': match.group(),
                'type': 'project',
                'start': match.start(),
                'end': match.end()
            })

    # Extract organizations
    for pattern in ORGANIZATION_PATTERNS:
        for match in re.finditer(pattern, text, re.IGNORECASE):
            entities.append({
                'text': match.group(),
                'type': 'organization',
                'start': match.start(),
                'end': match.end()
            })

    # Extract dates
    for pattern in DATE_PATTERNS:
        for match in re.finditer(pattern, text, re.IGNORECASE):
            entities.append({
                'text': match.group(),
                'type': 'date',
                'start': match.start(),
                'end': match.end()
            })

    return entities

def build_relationships(conversations, all_entities):
    """Build relationships between entities based on conversation context."""
    relationships = []
    seen_relationships = set()

    for conv in conversations:
        text = conv['text']
        speaker = conv['speaker']
        conv_entities = extract_entities(text)

        # Get unique entity texts in this conversation
        entity_texts = list(set(e['text'] for e in conv_entities))

        # Person works on project relationships
        for entity in conv_entities:
            if entity['type'] == 'person':
                for other in conv_entities:
                    if other['type'] == 'project' and entity['text'] != other['text']:
                        rel_key = (entity['text'], 'works_on', other['text'])
                        if rel_key not in seen_relationships:
                            relationships.append({
                                'source': entity['text'],
                                'target': other['text'],
                                'type': 'works_on',
                                'conversation_id': conv['id']
                            })
                            seen_relationships.add(rel_key)

            # Person mentioned with organization
            if entity['type'] == 'person':
                for other in conv_entities:
                    if other['type'] == 'organization':
                        rel_key = (entity['text'], 'mentioned_with', other['text'])
                        if rel_key not in seen_relationships:
                            relationships.append({
                                'source': entity['text'],
                                'target': other['text'],
                                'type': 'mentioned_with',
                                'conversation_id': conv['id']
                            })
                            seen_relationships.add(rel_key)

        # Project depends on project relationships
        projects_in_conv = [e['text'] for e in conv_entities if e['type'] == 'project']
        if len(projects_in_conv) > 1:
            # Check for dependency keywords
            if 'depends on' in text.lower():
                for i, proj in enumerate(projects_in_conv):
                    for j, dep_proj in enumerate(projects_in_conv):
                        if i != j:
                            rel_key = (proj, 'depends_on', dep_proj)
                            if rel_key not in seen_relationships:
                                relationships.append({
                                    'source': proj,
                                    'target': dep_proj,
                                    'type': 'depends_on',
                                    'conversation_id': conv['id']
                                })
                                seen_relationships.add(rel_key)

        # Project is for organization
        for entity in conv_entities:
            if entity['type'] == 'project':
                for other in conv_entities:
                    if other['type'] == 'organization':
                        rel_key = (entity['text'], 'client_of', other['text'])
                        if rel_key not in seen_relationships:
                            relationships.append({
                                'source': entity['text'],
                                'target': other['text'],
                                'type': 'client_of',
                                'conversation_id': conv['id']
                            })
                            seen_relationships.add(rel_key)

    return relationships

def create_summary(conversations, entities, relationships):
    """Create a human-readable summary."""
    lines = [
        "=" * 60,
        "PERCEPT AMBIENT CONTEXT - SUMMARY",
        "=" * 60,
        "",
        f"Generated: {datetime.now().isoformat()}",
        f"Conversations processed: {len(conversations)}",
        f"Total entities extracted: {len(entities)}",
        f"Total relationships built: {len(relationships)}",
        "",
        "-" * 60,
        "ENTITIES BY TYPE:",
        "-" * 60,
    ]

    # Group entities by type
    entity_types = {}
    for e in entities:
        if e['type'] not in entity_types:
            entity_types[e['type']] = set()
        entity_types[e['type']].add(e['text'])

    for etype, etexts in sorted(entity_types.items()):
        lines.append(f"  {etype.upper()}: {', '.join(sorted(etexts))}")

    lines.extend([
        "",
        "-" * 60,
        "KEY RELATIONSHIPS:",
        "-" * 60,
    ])

    for rel in relationships:
        lines.append(f"  {rel['source']} --[{rel['type']}]--> {rel['target']}")

    lines.extend([
        "",
        "-" * 60,
        "CONVERSATION HIGHLIGHTS:",
        "-" * 60,
    ])

    for conv in conversations:
        lines.append(f"  [{conv['id']}] {conv['speaker']}: {conv['text'][:80]}...")

    lines.extend([
        "",
        "=" * 60,
        "END OF SUMMARY",
        "=" * 60,
    ])

    return "\n".join(lines)

def create_context_packet(conversations, entities, relationships):
    """Create the machine-readable context packet."""
    # Deduplicate entities
    unique_entities = {}
    for e in entities:
        key = (e['text'], e['type'])
        if key not in unique_entities:
            unique_entities[key] = {
                'text': e['text'],
                'type': e['type'],
                'mentions': []
            }
        unique_entities[key]['mentions'].append(e.get('conversation_id', ''))

    resolved_entities = list(unique_entities.values())

    packet = {
        'metadata': {
            'generated_at': datetime.now().isoformat(),
            'version': '1.0',
            'total_conversations': len(conversations),
            'total_entities': len(resolved_entities),
            'total_relationships': len(relationships)
        },
        'recent_conversations': conversations,
        'resolved_entities': resolved_entities,
        'relationships': relationships,
        'relevant_history': [
            {
                'topic': 'Project Lumen',
                'summary': 'Project for Northstar Labs with deadline Friday. Depends on ambient dashboard and search index.',
                'key_people': ['Avery', 'Jordan', 'Mina'],
                'organization': 'Northstar Labs'
            }
        ]
    }

    return packet

def create_entities_csv(entities):
    """Create CSV data for entities."""
    # Deduplicate and add conversation IDs
    entity_rows = []
    seen = {}

    for e in entities:
        key = (e['text'], e['type'])
        if key not in seen:
            seen[key] = {'text': e['text'], 'type': e['type'], 'conversation_ids': []}
        seen[key]['conversation_ids'].append(e.get('conversation_id', ''))

    for key, data in seen.items():
        entity_rows.append({
            'entity_text': data['text'],
            'entity_type': data['type'],
            'conversation_ids': ';'.join(set(data['conversation_ids']))
        })

    return entity_rows

def main():
    # Read conversations
    data_path = Path('data/conversations.json')
    with open(data_path, 'r', encoding='utf-8') as f:
        conversations = json.load(f)

    # Extract all entities
    all_entities = []
    for conv in conversations:
        entities = extract_entities(conv['text'])
        for e in entities:
            e['conversation_id'] = conv['id']
        all_entities.extend(entities)

    # Build relationships
    relationships = build_relationships(conversations, all_entities)

    # Create summary
    summary = create_summary(conversations, all_entities, relationships)
    with open('summary.txt', 'w', encoding='utf-8') as f:
        f.write(summary)
    print("Created: summary.txt")

    # Create context packet
    context_packet = create_context_packet(conversations, all_entities, relationships)
    with open('context_packet.json', 'w', encoding='utf-8') as f:
        json.dump(context_packet, f, indent=2)
    print("Created: context_packet.json")

    # Create entities CSV
    csv_data = create_entities_csv(all_entities)
    with open('entities.csv', 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=['entity_text', 'entity_type', 'conversation_ids'])
        writer.writeheader()
        writer.writerows(csv_data)
    print("Created: entities.csv")

    print("\nAmbient context retrieval demo complete!")
    print("\n--- Summary Preview ---")
    print(summary[:500])

if __name__ == '__main__':
    main()
